  <a class="skip-link" href="#main">Skip to main content</a>

  <header>
    <p class="eyebrow">Image library</p>
    <h1>Image preview</h1>
  </header>

  <main id="main" tabindex="-1">
    <article class="preview-card" aria-labelledby="image-title">
      <div class="image-frame">
        <img
          class="image-preview"
          src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1200 750'%3E%3Cdefs%3E%3ClinearGradient id='sky' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0%25' stop-color='%230f172a'/%3E%3Cstop offset='45%25' stop-color='%23312e81'/%3E%3Cstop offset='100%25' stop-color='%23075985'/%3E%3C/linearGradient%3E%3ClinearGradient id='sun' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop stop-color='%23fde68a'/%3E%3Cstop offset='1' stop-color='%23fb7185'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1200' height='750' fill='url(%23sky)'/%3E%3Ccircle cx='905' cy='180' r='95' fill='url(%23sun)'/%3E%3Cpath d='M0 585 255 330 438 520 610 300 1200 620v130H0z' fill='%23020617'/%3E%3Cpath d='M0 650 210 480l140 100 185-150 210 160 120-90 335 165v85H0z' fill='%231e293b'/%3E%3Cpath d='M0 705c160-45 280-45 440 0s290 45 470 0 250-40 290-28v73H0z' fill='%230f766e'/%3E%3C/svg%3E"
          alt="Mountain landscape at dusk with a glowing sun and layered hills"
        >
      </div>
      <div class="preview-content">
        <div>
          <h2 id="image-title">Dusk over the ridge</h2>
          <p class="meta">Saved to Landscapes collection</p>
          <p class="status-message" id="status-message" tabindex="-1" aria-live="polite"></p>
        </div>
        <button class="trigger" type="button" aria-haspopup="dialog">Delete image</button>
      </div>
    </article>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog-inner">
      <div class="warning-icon" aria-hidden="true">!</div>
      <h2 id="dialog-title">Delete image?</h2>
      <p class="dialog-copy" id="dialog-description">
        This will remove "Dusk over the ridge" from your library. This action cannot be undone.
      </p>
      <div class="dialog-actions">
        <button class="cancel-button" type="button" value="cancel">Cancel</button>
        <button class="delete-confirm" type="button">Delete image</button>
      </div>
    </div>
  </dialog>

  <script>
    const trigger = document.querySelector(".trigger");
    const dialog = document.querySelector("#delete-dialog");
    const cancelButton = dialog.querySelector(".cancel-button");
    const confirmButton = dialog.querySelector(".delete-confirm");
    const statusMessage = document.querySelector("#status-message");
    let deleteConfirmed = false;

    function closeDialog() {
      dialog.close();
    }

    trigger.addEventListener("click", () => {
      deleteConfirmed = false;
      dialog.showModal();
      cancelButton.focus();
    });

    cancelButton.addEventListener("click", closeDialog);

    confirmButton.addEventListener("click", () => {
      deleteConfirmed = true;
      dialog.close();
      statusMessage.textContent = "Image deleted from your library.";
      trigger.textContent = "Image deleted";
      trigger.disabled = true;
      statusMessage.focus();
    });

    dialog.addEventListener("close", () => {
      if (!deleteConfirmed && !trigger.disabled) {
        trigger.focus();
      }
    });

    dialog.addEventListener("click", (event) => {
      if (event.target === dialog) {
        closeDialog();
      }
    });
  </script>
