      color: var(--text);
      line-height: 1.5;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 10;
      transform: translateY(-150%);
      border-radius: 999px;
      background: var(--text);
      color: var(--bg);
      padding: 0.75rem 1rem;
      font-weight: 700;
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    header,
    main {
      width: min(100% - 2rem, 72rem);
      margin-inline: auto;
    }

    header {
      padding: 2rem 0 1rem;
    }

    main {
      display: grid;
      min-height: calc(100vh - 7rem);
      place-items: center;
      padding: 1rem 0 3rem;
    }

    h1,
    h2,
    p {
      margin-top: 0;
    }

    h1 {
      margin-bottom: 0.25rem;
      font-size: clamp(1.75rem, 4vw, 3.25rem);
      letter-spacing: -0.04em;
    }

    .eyebrow,
    .meta,
    .dialog-copy {
      color: var(--muted);
    }

    .eyebrow {
      margin-bottom: 0;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .preview-card {
      width: min(100%, 52rem);
      overflow: hidden;
      border: 1px solid var(--border);
      border-radius: 1.5rem;
      background: linear-gradient(180deg, #172033, var(--surface));
      box-shadow: 0 2rem 5rem var(--shadow);
    }

    .image-frame {
      padding: clamp(1rem, 3vw, 1.5rem);
      background: #020617;
    }

    .image-preview {
      display: block;
      width: 100%;
      max-width: 100%;
      border-radius: 1rem;
      aspect-ratio: 16 / 10;
      object-fit: cover;
      background:
        linear-gradient(135deg, #0f172a 0 24%, transparent 24% 28%, #312e81 28% 42%, transparent 42% 48%, #075985 48% 68%, transparent 68%),
        linear-gradient(45deg, #1f2937, #020617);
      box-shadow: inset 0 0 0 1px #64748b;
    }

    .preview-content {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: clamp(1.25rem, 4vw, 2rem);
