      padding: clamp(1.25rem, 5vw, 2rem);
    }

    .warning-icon {
      display: grid;
      width: 3.25rem;
      height: 3.25rem;
      margin-bottom: 1rem;
      place-items: center;
      border: 1px solid var(--danger);
      border-radius: 999px;
      background: #450a0a;
      color: #fecaca;
      font-size: 1.5rem;
      font-weight: 900;
    }

    .dialog-inner h2 {
      margin-bottom: 0.5rem;
      font-size: clamp(1.4rem, 5vw, 2rem);
      letter-spacing: -0.03em;
    }

    .dialog-copy {
      margin-bottom: 1.5rem;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
      flex-wrap: wrap;
